WITH ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY event_type ORDER BY duration_sec DESC, id) AS latest_rank FROM web_events) ranked WHERE latest_rank = 1) SELECT DATE_TRUNC('QUARTER', event_time) AS quarter_start, SIZE(COLLECT_SET(event_type)) AS num_event_types, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS span_minutes, COUNT(DISTINCT session_id) AS distinct_session_ids, COUNT(DISTINCT page) AS distinct_pages, COUNT(*) FILTER (WHERE page = '/product') AS product_rows, APPROX_PERCENTILE(duration_sec, 0.5) AS duration_sec_p50 FROM ranked GROUP BY DATE_TRUNC('QUARTER', event_time);
